-- from 20261201300000_delivery_ads_canonical_finance_ast004_ast005.sql
CREATE OR REPLACE FUNCTION public.ensure_business_cash_account(p_store_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  INSERT INTO public.business_cash_accounts (store_id, balance_minor)
  VALUES (p_store_id, 0)
  ON CONFLICT (store_id) DO NOTHING;
END;
$$;

-- from 20261201300000_delivery_ads_canonical_finance_ast004_ast005.sql
CREATE OR REPLACE FUNCTION public.delivery_ad_campaign_funding_allows_active(
  p_product_kind text,
  p_campaign_id uuid,
  p_campaign_source text
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF coalesce(p_campaign_source, 'OWNER_PAID') = 'DIBAY_FIRST_PARTY' THEN
    RETURN true;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.delivery_ad_canonical_bc_fundings f
    WHERE f.application_id = p_campaign_id
      AND f.product_kind = p_product_kind
      AND f.status = 'SECURED'
  ) THEN
    RETURN true;
  END IF;
  -- Legacy Stage 1 Store Cash spends (historical)
  IF p_product_kind IN ('store_sponsored', 'banner') AND EXISTS (
    SELECT 1 FROM public.delivery_ad_store_cash_spends s
    WHERE s.campaign_id = p_campaign_id
      AND s.product_kind = p_product_kind
      AND s.status = 'SECURED'
  ) THEN
    RETURN true;
  END IF;
  RETURN false;
END;
$$;

-- from 20261203170000_platform_popup_bc_spend_ledger_column_fix.sql
CREATE OR REPLACE FUNCTION public.business_cash_delivery_ad_spend(
  p_owner_user_id uuid,
  p_store_id uuid,
  p_application_id uuid,
  p_product_kind text,
  p_amount_minor bigint DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing public.delivery_ad_canonical_bc_fundings;
  v_store record;
  v_camp record;
  v_snap public.delivery_ad_campaign_commercial_snapshots;
  v_req public.platform_popup_owner_requests;
  v_amount_minor bigint;
  v_bal bigint;
  v_new bigint;
  v_ledger uuid;
  v_fund uuid;
BEGIN
  IF p_owner_user_id IS NULL OR p_store_id IS NULL OR p_application_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF p_product_kind NOT IN ('store_sponsored', 'banner', 'partner', 'platform_popup') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;

  SELECT * INTO v_existing
  FROM public.delivery_ad_canonical_bc_fundings
  WHERE product_kind = p_product_kind AND application_id = p_application_id
  FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status = 'SECURED' THEN
      RETURN jsonb_build_object(
        'ok', true, 'idempotent', true, 'status', 'SECURED',
        'funding_id', v_existing.id,
        'amount_minor', v_existing.amount_minor,
        'spend_ledger_id', v_existing.spend_ledger_id
      );
    END IF;
    IF v_existing.status = 'REFUNDED' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'already_refunded');
    END IF;
  END IF;

  SELECT id, owner_user_id INTO v_store FROM public.stores WHERE id = p_store_id FOR UPDATE;
  IF NOT FOUND OR v_store.owner_user_id IS DISTINCT FROM p_owner_user_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  IF p_product_kind IN ('partner', 'platform_popup') THEN
    IF p_amount_minor IS NULL OR p_amount_minor <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_amount');
    END IF;
    IF p_product_kind = 'platform_popup' THEN
      SELECT * INTO v_req
      FROM public.platform_popup_owner_requests
      WHERE id = p_application_id
      FOR UPDATE;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('ok', false, 'error', 'request_not_found');
      END IF;
      IF v_req.owner_user_id IS DISTINCT FROM p_owner_user_id
         OR v_req.store_id IS DISTINCT FROM p_store_id THEN
        RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
      END IF;
      IF v_req.request_status NOT IN ('draft', 'revision_required') THEN
        RETURN jsonb_build_object('ok', false, 'error', 'not_debit_eligible', 'status', v_req.request_status);
      END IF;
      IF v_req.price_minor IS NULL OR v_req.price_minor <= 0 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'price_missing');
      END IF;
      IF p_amount_minor IS DISTINCT FROM v_req.price_minor THEN
        RETURN jsonb_build_object('ok', false, 'error', 'amount_mismatch');
      END IF;
    END IF;
    v_amount_minor := p_amount_minor;
  ELSE
    IF p_product_kind = 'banner' THEN
      SELECT id, store_id, owner_user_id, lifecycle_status, campaign_source
        INTO v_camp
      FROM public.store_banner_ad_campaigns
      WHERE id = p_application_id
      FOR UPDATE;
    ELSE
      SELECT id, store_id, owner_user_id, lifecycle_status, campaign_source
        INTO v_camp
      FROM public.store_paid_ad_campaigns
      WHERE id = p_application_id
      FOR UPDATE;
    END IF;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
    END IF;
    IF v_camp.owner_user_id IS DISTINCT FROM p_owner_user_id
       OR v_camp.store_id IS DISTINCT FROM p_store_id THEN
      RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
    END IF;
    IF coalesce(v_camp.campaign_source, 'OWNER_PAID') = 'DIBAY_FIRST_PARTY' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'first_party_no_bc');
    END IF;
    IF v_camp.lifecycle_status NOT IN ('DRAFT', 'CHANGES_REQUESTED') THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'not_debit_eligible',
        'lifecycle', v_camp.lifecycle_status
      );
    END IF;

    SELECT * INTO v_snap
    FROM public.delivery_ad_campaign_commercial_snapshots
    WHERE campaign_id = p_application_id AND product_kind = p_product_kind;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'snapshot_missing');
    END IF;
    IF v_snap.campaign_source IS DISTINCT FROM 'OWNER_PAID' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'first_party_no_bc');
    END IF;
    IF v_snap.commercial_status IS DISTINCT FROM 'PRICED' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'snapshot_not_priced');
    END IF;
    IF v_snap.final_payable_minor IS NULL OR v_snap.final_payable_minor <= 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_payable');
    END IF;
    v_amount_minor := v_snap.final_payable_minor;
  END IF;

  PERFORM public.ensure_business_cash_account(p_store_id);
  SELECT balance_minor INTO v_bal FROM public.business_cash_accounts WHERE store_id = p_store_id FOR UPDATE;
  IF v_bal < v_amount_minor THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'INSUFFICIENT_BUSINESS_CASH',
      'available_minor', v_bal,
      'required_minor', v_amount_minor,
      'shortage_minor', v_amount_minor - v_bal,
      'available_php', (v_bal / 100)::integer,
      'required_php', (v_amount_minor / 100)::integer,
      'shortage_php', ((v_amount_minor - v_bal) / 100)::integer,
      'currency', 'PHP'
    );
  END IF;

  v_new := v_bal - v_amount_minor;
  UPDATE public.business_cash_accounts
  SET balance_minor = v_new, updated_at = now()
  WHERE store_id = p_store_id;

  INSERT INTO public.business_cash_ledger (
    store_id, entry_kind, direction, amount_minor, balance_after_minor,
    related_type, related_id, idempotency_key, actor_type, actor_user_id
  ) VALUES (
    p_store_id,
    CASE WHEN p_product_kind = 'partner' THEN 'PARTNER_SPEND' ELSE 'AD_SPEND' END,
    'debit', v_amount_minor, v_new,
    p_product_kind, p_application_id::text,
    'bc_spend:' || p_product_kind || ':' || p_application_id::text,
    'owner', p_owner_user_id
  ) RETURNING id INTO v_ledger;

  INSERT INTO public.delivery_ad_canonical_bc_fundings (
    store_id, product_kind, application_id, amount_minor,
    spend_ledger_id, status
  ) VALUES (
    p_store_id, p_product_kind, p_application_id, v_amount_minor,
    v_ledger, 'SECURED'
  ) RETURNING id INTO v_fund;

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'status', 'SECURED',
    'funding_id', v_fund,
    'spend_ledger_id', v_ledger,
    'amount_minor', v_amount_minor,
    'balance_after_minor', v_new
  );
END;
$$;

-- from 20261203170000_platform_popup_bc_spend_ledger_column_fix.sql
CREATE OR REPLACE FUNCTION public.business_cash_delivery_ad_refund(
  p_admin_user_id uuid,
  p_application_id uuid,
  p_product_kind text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_fund public.delivery_ad_canonical_bc_fundings;
  v_bal bigint;
  v_ledger uuid;
BEGIN
  IF p_admin_user_id IS NULL OR p_application_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF p_product_kind NOT IN ('store_sponsored', 'banner', 'partner', 'platform_popup') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;

  SELECT * INTO v_fund
  FROM public.delivery_ad_canonical_bc_fundings
  WHERE product_kind = p_product_kind AND application_id = p_application_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'funding_not_found');
  END IF;
  IF v_fund.status = 'REFUNDED' THEN
    RETURN jsonb_build_object(
      'ok', true, 'idempotent', true, 'funding_id', v_fund.id,
      'refund_ledger_id', v_fund.refund_ledger_id,
      'amount_minor', v_fund.amount_minor,
      'status', 'REFUNDED'
    );
  END IF;
  IF v_fund.status IS DISTINCT FROM 'SECURED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_secured');
  END IF;

  PERFORM public.ensure_business_cash_account(v_fund.store_id);
  UPDATE public.business_cash_accounts
  SET balance_minor = balance_minor + v_fund.amount_minor, updated_at = now()
  WHERE store_id = v_fund.store_id
  RETURNING balance_minor INTO v_bal;

  INSERT INTO public.business_cash_ledger (
    store_id, entry_kind, direction, amount_minor, balance_after_minor,
    related_type, related_id, idempotency_key, actor_type, actor_user_id
  ) VALUES (
    v_fund.store_id,
    CASE WHEN p_product_kind = 'partner' THEN 'PARTNER_REFUND' ELSE 'AD_REFUND' END,
    'credit', v_fund.amount_minor, v_bal,
    'delivery_ad_canonical_bc_fundings', v_fund.id::text,
    'bc_refund:' || p_product_kind || ':' || p_application_id::text,
    'admin', p_admin_user_id
  ) RETURNING id INTO v_ledger;

  UPDATE public.delivery_ad_canonical_bc_fundings
  SET
    status = 'REFUNDED',
    refund_ledger_id = v_ledger,
    refunded_at = now(),
    updated_at = now()
  WHERE id = v_fund.id;

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'status', 'REFUNDED',
    'funding_id', v_fund.id,
    'refund_ledger_id', v_ledger,
    'amount_minor', v_fund.amount_minor
  );
END;
$$;

-- from 20261201220000_delivery_ads_cut3b_operations_timeline.sql
CREATE OR REPLACE FUNCTION public.admin_delivery_ad_transition(
  p_admin_user_id uuid,
  p_product_kind text,
  p_campaign_id uuid,
  p_action text,
  p_expected_lifecycle text,
  p_expected_updated_at timestamptz,
  p_reason text DEFAULT NULL,
  p_owner_visible_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_table text;
  v_row record;
  v_from text;
  v_to text;
  v_review text;
  v_is_active boolean;
  v_now timestamptz := now();
  v_go_live text;
  v_audit_action text;
  v_audit_id uuid;
  v_source text;
BEGIN
  IF p_admin_user_id IS NULL OR p_campaign_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  IF NOT public.is_platform_admin(p_admin_user_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  IF p_product_kind NOT IN ('store_sponsored', 'banner') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;

  v_table := CASE
    WHEN p_product_kind = 'banner' THEN 'store_banner_ad_campaigns'
    ELSE 'store_paid_ad_campaigns'
  END;

  IF p_product_kind = 'banner' THEN
    SELECT * INTO v_row FROM public.store_banner_ad_campaigns WHERE id = p_campaign_id FOR UPDATE;
  ELSE
    SELECT * INTO v_row FROM public.store_paid_ad_campaigns WHERE id = p_campaign_id FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
  END IF;

  v_from := v_row.lifecycle_status;
  v_source := coalesce(v_row.campaign_source, 'OWNER_PAID');

  IF p_expected_lifecycle IS NOT NULL AND v_from IS DISTINCT FROM p_expected_lifecycle THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_lifecycle', 'current', v_from);
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_row.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_updated_at');
  END IF;

  IF p_action = 'start_review' THEN
    v_to := 'UNDER_REVIEW'; v_review := 'IN_REVIEW'; v_audit_action := 'review_started';
  ELSIF p_action = 'request_changes' THEN
    IF length(trim(coalesce(p_reason, ''))) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'reason_required');
    END IF;
    v_to := 'CHANGES_REQUESTED'; v_review := 'CHANGES_REQUESTED'; v_audit_action := 'changes_requested';
  ELSIF p_action = 'approve' THEN
    v_to := 'APPROVED'; v_review := 'APPROVED'; v_audit_action := 'approved';
  ELSIF p_action = 'reject' THEN
    IF length(trim(coalesce(p_reason, ''))) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'reason_required');
    END IF;
    v_to := 'REJECTED'; v_review := 'REJECTED'; v_audit_action := 'rejected';
  ELSIF p_action = 'pause' THEN
    IF length(trim(coalesce(p_reason, ''))) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'reason_required');
    END IF;
    v_to := 'PAUSED_ADMIN'; v_review := NULL; v_audit_action := 'paused_admin';
  ELSIF p_action = 'resume' THEN
    v_to := 'ACTIVE'; v_review := NULL; v_audit_action := 'resumed_admin';
  ELSIF p_action = 'end' THEN
    v_to := 'ENDED'; v_review := NULL; v_audit_action := 'ended_admin';
  ELSIF p_action = 'terminate' THEN
    IF length(trim(coalesce(p_reason, ''))) = 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'reason_required');
    END IF;
    v_to := 'TERMINATED'; v_review := NULL; v_audit_action := 'terminated_admin';
  ELSIF p_action = 'archive' THEN
    v_to := 'ARCHIVED'; v_review := NULL; v_audit_action := 'archived';
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_action');
  END IF;

  IF p_action = 'approve' THEN
    IF v_from IS DISTINCT FROM 'UNDER_REVIEW' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'illegal_transition', 'from', v_from, 'to', 'APPROVED');
    END IF;
  ELSIF NOT (
    (v_from = 'SUBMITTED' AND v_to = 'UNDER_REVIEW') OR
    (v_from = 'UNDER_REVIEW' AND v_to IN ('CHANGES_REQUESTED','REJECTED')) OR
    (v_from IN ('ACTIVE','SCHEDULED') AND v_to = 'PAUSED_ADMIN') OR
    (v_from = 'PAUSED_ADMIN' AND v_to = 'ACTIVE') OR
    (v_from IN ('ACTIVE','SCHEDULED','PAUSED_ADMIN','PAUSED_OWNER') AND v_to IN ('ENDED','TERMINATED')) OR
    (v_from IN ('ENDED','REJECTED','TERMINATED') AND v_to = 'ARCHIVED') OR
    (v_from = 'CHANGES_REQUESTED' AND v_to IN ('UNDER_REVIEW','REJECTED'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'illegal_transition', 'from', v_from, 'to', v_to);
  END IF;

  IF p_action = 'approve' THEN
    IF v_row.start_at > v_now THEN
      v_go_live := 'SCHEDULED';
    ELSE
      v_go_live := 'ACTIVE';
    END IF;
    v_to := v_go_live;
  END IF;

  -- MODEL B: OWNER_PAID cannot enter ACTIVE without FUNDED Business Cash
  IF v_to = 'ACTIVE' AND NOT public.delivery_ad_campaign_funding_allows_active(
    p_product_kind, p_campaign_id, v_source
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'funding_required');
  END IF;

  v_is_active := (v_to IN ('ACTIVE','SCHEDULED'));

  IF p_product_kind = 'banner' THEN
    UPDATE public.store_banner_ad_campaigns SET
      lifecycle_status = v_to,
      is_active = v_is_active,
      review_status = COALESCE(v_review, review_status),
      review_notes = CASE
        WHEN p_action IN ('request_changes','reject','pause','terminate')
          THEN nullif(trim(coalesce(p_owner_visible_notes, p_reason)), '')
        WHEN p_action = 'approve' THEN NULL
        ELSE review_notes
      END,
      reviewed_at = CASE WHEN p_action IN ('approve','reject','request_changes','start_review') THEN v_now ELSE reviewed_at END,
      approved_at = CASE WHEN p_action = 'approve' THEN v_now ELSE approved_at END,
      activated_at = CASE WHEN v_to = 'ACTIVE' THEN COALESCE(activated_at, v_now) ELSE activated_at END,
      paused_at = CASE WHEN v_to = 'PAUSED_ADMIN' THEN v_now ELSE paused_at END,
      ended_at = CASE WHEN v_to IN ('ENDED','TERMINATED') THEN v_now ELSE ended_at END,
      archived_at = CASE WHEN v_to = 'ARCHIVED' THEN v_now ELSE archived_at END,
      updated_by_user_id = p_admin_user_id,
      updated_at = v_now
    WHERE id = p_campaign_id;

    IF p_action = 'approve' AND v_row.creative_id IS NOT NULL THEN
      UPDATE public.delivery_ad_creatives
      SET review_status = 'APPROVED', updated_at = v_now
      WHERE id = v_row.creative_id;
    ELSIF p_action = 'reject' AND v_row.creative_id IS NOT NULL THEN
      UPDATE public.delivery_ad_creatives
      SET review_status = 'REJECTED', updated_at = v_now
      WHERE id = v_row.creative_id;
    ELSIF p_action = 'request_changes' AND v_row.creative_id IS NOT NULL THEN
      UPDATE public.delivery_ad_creatives
      SET review_status = 'CHANGES_REQUESTED', updated_at = v_now
      WHERE id = v_row.creative_id;
    END IF;
  ELSE
    UPDATE public.store_paid_ad_campaigns SET
      lifecycle_status = v_to,
      is_active = v_is_active,
      review_status = COALESCE(v_review, review_status),
      review_notes = CASE
        WHEN p_action IN ('request_changes','reject','pause','terminate')
          THEN nullif(trim(coalesce(p_owner_visible_notes, p_reason)), '')
        WHEN p_action = 'approve' THEN NULL
        ELSE review_notes
      END,
      reviewed_at = CASE WHEN p_action IN ('approve','reject','request_changes','start_review') THEN v_now ELSE reviewed_at END,
      approved_at = CASE WHEN p_action = 'approve' THEN v_now ELSE approved_at END,
      activated_at = CASE WHEN v_to = 'ACTIVE' THEN COALESCE(activated_at, v_now) ELSE activated_at END,
      paused_at = CASE WHEN v_to = 'PAUSED_ADMIN' THEN v_now ELSE paused_at END,
      ended_at = CASE WHEN v_to IN ('ENDED','TERMINATED') THEN v_now ELSE ended_at END,
      archived_at = CASE WHEN v_to = 'ARCHIVED' THEN v_now ELSE archived_at END,
      updated_by_user_id = p_admin_user_id,
      updated_at = v_now
    WHERE id = p_campaign_id;
  END IF;

  INSERT INTO public.delivery_ad_audit_logs (
    product_kind, campaign_id, actor_type, actor_user_id, action, reason, before_json, after_json
  ) VALUES (
    p_product_kind, p_campaign_id, 'admin', p_admin_user_id, v_audit_action,
    nullif(trim(coalesce(p_reason, '')), ''),
    jsonb_build_object('lifecycle', v_from, 'updated_at', v_row.updated_at),
    jsonb_build_object('lifecycle', v_to, 'action', p_action)
  )
  RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'ok', true,
    'campaign_id', p_campaign_id,
    'from', v_from,
    'to', v_to,
    'action', p_action,
    'audit_id', v_audit_id
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'db_error', 'detail', SQLERRM);
END;
$$;

-- from 20261201197000_delivery_ads_business_cash_funding_gate.sql
CREATE OR REPLACE FUNCTION public.delivery_ad_system_schedule_transition(
  p_product_kind text,
  p_campaign_id uuid,
  p_action text,
  p_expected_lifecycle text,
  p_expected_updated_at timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row record;
  v_from text;
  v_to text;
  v_now timestamptz := now();
  v_audit_action text;
  v_audit_id uuid;
  v_is_active boolean;
  v_source text;
BEGIN
  IF p_campaign_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
  END IF;

  IF p_product_kind NOT IN ('store_sponsored', 'banner') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;

  IF p_action NOT IN ('activate_due', 'end_due') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_action');
  END IF;

  IF p_product_kind = 'banner' THEN
    SELECT * INTO v_row FROM public.store_banner_ad_campaigns WHERE id = p_campaign_id FOR UPDATE;
  ELSE
    SELECT * INTO v_row FROM public.store_paid_ad_campaigns WHERE id = p_campaign_id FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
  END IF;

  v_from := v_row.lifecycle_status;
  v_source := coalesce(v_row.campaign_source, 'OWNER_PAID');

  IF p_expected_lifecycle IS NOT NULL AND v_from IS DISTINCT FROM p_expected_lifecycle THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_lifecycle', 'current', v_from);
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_row.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_updated_at');
  END IF;

  IF p_action = 'activate_due' THEN
    IF v_from IS DISTINCT FROM 'SCHEDULED' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'illegal_transition', 'from', v_from, 'to', 'ACTIVE');
    END IF;
    IF v_row.start_at > v_now THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_due', 'detail', 'start_at_future');
    END IF;
    IF v_row.end_at <= v_now THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_due', 'detail', 'end_at_passed');
    END IF;
    IF NOT public.delivery_ad_campaign_funding_allows_active(
      p_product_kind, p_campaign_id, v_source
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'funding_required');
    END IF;
    v_to := 'ACTIVE';
    v_audit_action := 'system_activated';
  ELSE
    IF v_from NOT IN ('ACTIVE', 'SCHEDULED') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'illegal_transition', 'from', v_from, 'to', 'ENDED');
    END IF;
    IF v_row.end_at > v_now THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_due', 'detail', 'end_at_future');
    END IF;
    v_to := 'ENDED';
    v_audit_action := 'system_ended';
  END IF;

  v_is_active := (v_to IN ('ACTIVE', 'SCHEDULED'));

  IF p_product_kind = 'banner' THEN
    UPDATE public.store_banner_ad_campaigns SET
      lifecycle_status = v_to,
      is_active = v_is_active,
      activated_at = CASE WHEN v_to = 'ACTIVE' THEN COALESCE(activated_at, v_now) ELSE activated_at END,
      ended_at = CASE WHEN v_to = 'ENDED' THEN v_now ELSE ended_at END,
      updated_at = v_now
    WHERE id = p_campaign_id;
  ELSE
    UPDATE public.store_paid_ad_campaigns SET
      lifecycle_status = v_to,
      is_active = v_is_active,
      activated_at = CASE WHEN v_to = 'ACTIVE' THEN COALESCE(activated_at, v_now) ELSE activated_at END,
      ended_at = CASE WHEN v_to = 'ENDED' THEN v_now ELSE ended_at END,
      updated_at = v_now
    WHERE id = p_campaign_id;
  END IF;

  INSERT INTO public.delivery_ad_audit_logs (
    product_kind, campaign_id, actor_type, actor_user_id, action, reason, before_json, after_json
  ) VALUES (
    p_product_kind,
    p_campaign_id,
    'system',
    NULL,
    v_audit_action,
    NULL,
    jsonb_build_object('lifecycle', v_from, 'updated_at', v_row.updated_at),
    jsonb_build_object('lifecycle', v_to, 'action', p_action)
  )
  RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'ok', true,
    'campaign_id', p_campaign_id,
    'from', v_from,
    'to', v_to,
    'action', p_action,
    'audit_id', v_audit_id
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'db_error', 'detail', SQLERRM);
END;
$$;

-- from 20270421120400_finance_ssot19_d2_delivery_ads.sql
CREATE OR REPLACE FUNCTION public.owner_delivery_ad_transition(
  p_owner_user_id uuid,
  p_product_kind text,
  p_campaign_id uuid,
  p_action text,
  p_expected_lifecycle text,
  p_audit_action text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row record;
  v_from text;
  v_to text;
  v_is_active boolean;
  v_now timestamptz := now();
  v_audit_id uuid;
  v_before jsonb;
  v_after jsonb;
BEGIN
  IF p_owner_user_id IS NULL OR p_campaign_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  IF p_product_kind NOT IN ('store_sponsored', 'banner') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;

  IF p_action NOT IN ('submit', 'resubmit', 'pause', 'resume', 'end') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_action');
  END IF;

  IF p_expected_lifecycle IS NULL OR length(trim(p_expected_lifecycle)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_lifecycle');
  END IF;

  IF p_audit_action IS NULL OR length(trim(p_audit_action)) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_action');
  END IF;

  -- Lock + ownership (trusted caller = service_role after TS Owner gate)
  IF p_product_kind = 'banner' THEN
    SELECT * INTO v_row
    FROM public.store_banner_ad_campaigns
    WHERE id = p_campaign_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_row
    FROM public.store_paid_ad_campaigns
    WHERE id = p_campaign_id
    FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'campaign_not_found');
  END IF;

  IF v_row.owner_user_id IS DISTINCT FROM p_owner_user_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  v_from := v_row.lifecycle_status;

  -- CAS: expected lifecycle must match locked row
  IF v_from IS DISTINCT FROM p_expected_lifecycle THEN
    RETURN jsonb_build_object('ok', false, 'error', 'stale_lifecycle', 'current', v_from);
  END IF;

  -- Resolve target from Owner action (mirrors ownerActionTargetLifecycle)
  IF p_action IN ('submit', 'resubmit') THEN
    v_to := 'SUBMITTED';
  ELSIF p_action = 'pause' THEN
    v_to := 'PAUSED_OWNER';
  ELSIF p_action = 'resume' THEN
    v_to := 'ACTIVE';
  ELSIF p_action = 'end' THEN
    v_to := 'ENDED';
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_action');
  END IF;

  -- Owner allowlist (mirrors delivery-ad-lifecycle OWNER edges). PAUSED_ADMIN resume blocked.
  IF NOT (
    (v_from = 'DRAFT' AND v_to = 'SUBMITTED') OR
    (v_from = 'CHANGES_REQUESTED' AND v_to = 'SUBMITTED') OR
    (v_from = 'ACTIVE' AND v_to = 'PAUSED_OWNER') OR
    (v_from = 'PAUSED_OWNER' AND v_to = 'ACTIVE') OR
    (v_from = 'PAUSED_OWNER' AND v_to = 'ENDED') OR
    (v_from = 'ACTIVE' AND v_to = 'ENDED')
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'illegal_transition', 'from', v_from, 'to', v_to);
  END IF;

  -- SSOT-19 F-09: an OWNER_PAID submission must be funded (Cash SECURED).
  IF p_action IN ('submit', 'resubmit')
     AND NOT public.delivery_ad_campaign_funding_allows_active(
       p_product_kind, p_campaign_id, v_row.campaign_source
     ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'funding_required');
  END IF;

  -- Sponsored resume: end_at must still be in the future (existing TS semantics)
  IF p_product_kind = 'store_sponsored' AND v_from = 'PAUSED_OWNER' AND v_to = 'ACTIVE' THEN
    IF v_row.end_at IS NULL OR v_row.end_at <= v_now THEN
      RETURN jsonb_build_object('ok', false, 'error', 'illegal_transition', 'from', v_from, 'to', v_to);
    END IF;
  END IF;

  v_is_active := (v_to IN ('ACTIVE', 'SCHEDULED'));

  IF p_product_kind = 'banner' THEN
    v_before := jsonb_build_object('lifecycle', v_from);
  ELSE
    v_before := jsonb_build_object(
      'lifecycle_status', v_from,
      'review_status', v_row.review_status
    );
  END IF;

  IF p_product_kind = 'banner' THEN
    -- Banner field patches mirror prior owner-banner-writer transition (no resume timestamp clear)
    UPDATE public.store_banner_ad_campaigns SET
      lifecycle_status = v_to,
      is_active = v_is_active,
      review_status = CASE
        WHEN v_to = 'SUBMITTED' THEN 'PENDING'
        ELSE review_status
      END,
      submitted_at = CASE
        WHEN v_to = 'SUBMITTED' THEN v_now
        ELSE submitted_at
      END,
      paused_at = CASE
        WHEN v_to = 'PAUSED_OWNER' THEN v_now
        ELSE paused_at
      END,
      ended_at = CASE
        WHEN v_to = 'ENDED' THEN v_now
        ELSE ended_at
      END,
      updated_by_user_id = p_owner_user_id,
      updated_at = v_now
    WHERE id = p_campaign_id;

    IF p_action IN ('submit', 'resubmit') AND v_row.creative_id IS NOT NULL THEN
      UPDATE public.delivery_ad_creatives
      SET review_status = 'PENDING', updated_at = v_now
      WHERE id = v_row.creative_id;
    END IF;
  ELSE
    UPDATE public.store_paid_ad_campaigns SET
      lifecycle_status = v_to,
      is_active = CASE WHEN v_to = 'ENDED' THEN false ELSE v_is_active END,
      review_status = CASE
        WHEN v_to = 'SUBMITTED' THEN 'PENDING'
        ELSE review_status
      END,
      submitted_at = CASE
        WHEN v_to = 'SUBMITTED' THEN v_now
        ELSE submitted_at
      END,
      paused_at = CASE
        WHEN v_to = 'PAUSED_OWNER' THEN v_now
        WHEN v_from = 'PAUSED_OWNER' AND v_to = 'ACTIVE' THEN NULL
        ELSE paused_at
      END,
      activated_at = CASE
        WHEN v_from = 'PAUSED_OWNER' AND v_to = 'ACTIVE' THEN v_now
        ELSE activated_at
      END,
      ended_at = CASE
        WHEN v_to = 'ENDED' THEN v_now
        ELSE ended_at
      END,
      updated_by_user_id = p_owner_user_id,
      updated_at = v_now
    WHERE id = p_campaign_id;
  END IF;

  IF p_product_kind = 'banner' THEN
    v_after := jsonb_build_object('lifecycle', v_to);
  ELSE
    v_after := jsonb_build_object(
      'lifecycle_status', v_to,
      'review_status', CASE WHEN v_to = 'SUBMITTED' THEN 'PENDING' ELSE v_row.review_status END
    );
  END IF;

  INSERT INTO public.delivery_ad_audit_logs (
    product_kind, campaign_id, actor_type, actor_user_id, action, reason, before_json, after_json
  ) VALUES (
    p_product_kind,
    p_campaign_id,
    'owner',
    p_owner_user_id,
    p_audit_action,
    NULL,
    v_before,
    v_after
  )
  RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'ok', true,
    'campaign_id', p_campaign_id,
    'from', v_from,
    'to', v_to,
    'action', p_action,
    'audit_id', v_audit_id
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'db_error', 'detail', SQLERRM);
END;
$$;

-- from 20270523120300_owner_submit_delivery_ad_with_business_cash_atomic.sql (minus the in-body Korean comment line: not in production prosrc)
CREATE OR REPLACE FUNCTION public.owner_submit_delivery_ad_with_business_cash(
  p_owner_user_id uuid,
  p_store_id uuid,
  p_product_kind text,
  p_campaign_id uuid,
  p_action text,
  p_expected_lifecycle text,
  p_audit_action text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cash jsonb;
  v_tr jsonb;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF p_product_kind NOT IN ('store_sponsored', 'banner') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;
  IF p_action NOT IN ('submit', 'resubmit') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_action');
  END IF;

  BEGIN
    v_cash := public.business_cash_delivery_ad_spend(
      p_owner_user_id, p_store_id, p_campaign_id, p_product_kind, NULL
    );
    IF coalesce((v_cash->>'ok')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'ok', false,
        'stage', 'cash',
        'error', coalesce(v_cash->>'error', 'debit_failed'),
        'cash', v_cash
      );
    END IF;

    v_tr := public.owner_delivery_ad_transition(
      p_owner_user_id, p_product_kind, p_campaign_id, p_action,
      p_expected_lifecycle, p_audit_action
    );
    IF coalesce((v_tr->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION USING ERRCODE = 'DA502', MESSAGE = 'delivery_ad_submit_transition_failed';
    END IF;
  EXCEPTION WHEN SQLSTATE 'DA502' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'stage', 'transition',
      'error', coalesce(v_tr->>'error', 'transition_failed'),
      'transition', v_tr
    );
  END;

  RETURN v_tr || jsonb_build_object('cash', v_cash);
END;
$$;

-- from 20270523120200_admin_delivery_ad_reject_with_refund_atomic.sql (minus the in-body Korean comment line: not in production prosrc)
CREATE OR REPLACE FUNCTION public.admin_delivery_ad_reject_with_refund(
  p_admin_user_id uuid,
  p_product_kind text,
  p_campaign_id uuid,
  p_expected_lifecycle text,
  p_expected_updated_at timestamptz,
  p_reason text DEFAULT NULL,
  p_owner_visible_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tr jsonb;
  v_refund jsonb;
BEGIN
  IF (SELECT auth.role()) IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF p_product_kind NOT IN ('store_sponsored', 'banner') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_product');
  END IF;

  BEGIN
    v_tr := public.admin_delivery_ad_transition(
      p_admin_user_id, p_product_kind, p_campaign_id, 'reject',
      p_expected_lifecycle, p_expected_updated_at, p_reason, p_owner_visible_notes
    );
    IF coalesce((v_tr->>'ok')::boolean, false) IS NOT TRUE THEN
      RETURN v_tr;
    END IF;

    v_refund := public.business_cash_delivery_ad_refund(p_admin_user_id, p_campaign_id, p_product_kind);
    IF coalesce((v_refund->>'ok')::boolean, false) IS NOT TRUE
       AND coalesce(v_refund->>'error', '') <> 'funding_not_found' THEN
      RAISE EXCEPTION USING ERRCODE = 'DA501', MESSAGE = 'delivery_ad_reject_refund_failed';
    END IF;
  EXCEPTION WHEN SQLSTATE 'DA501' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'refund_failed',
      'detail', coalesce(v_refund->>'error', 'refund_failed')
    );
  END;

  RETURN v_tr || jsonb_build_object(
    'refund', v_refund,
    'refunded', coalesce((v_refund->>'ok')::boolean, false)
  );
END;
$$;

-- from 20270601100100_r7_admin_delivery_ad_campaigns_page.sql
CREATE OR REPLACE FUNCTION public.admin_delivery_ad_campaign_index(p_pending_asset text)
RETURNS TABLE (
  product_kind text,
  id uuid,
  store_id uuid,
  owner_user_id uuid,
  lifecycle_status text,
  review_status text,
  review_notes text,
  title text,
  headline text,
  image_url text,
  campaign_source text,
  start_at timestamptz,
  end_at timestamptz,
  submitted_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz,
  inventory_keys text[],
  store_name text,
  store_primary_slug text,
  store_sub_slug text,
  list_bucket text,
  sort_order integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH camp AS (
    SELECT 'store_sponsored'::text AS product_kind, c.id, c.store_id, c.owner_user_id,
           coalesce(c.lifecycle_status, 'DRAFT') AS lifecycle_status, c.review_status, c.review_notes,
           c.title, c.headline, c.image_url, coalesce(c.campaign_source, 'OWNER_PAID') AS campaign_source,
           c.start_at, c.end_at, c.submitted_at, c.created_at, c.updated_at,
           ARRAY(SELECT i.key FROM public.delivery_store_sponsored_campaign_inventories ci
                   JOIN public.delivery_ad_inventories i ON i.id = ci.inventory_id
                  WHERE ci.campaign_id = c.id ORDER BY ci.priority, ci.created_at, i.key) AS inventory_keys,
           NULL::integer AS sort_order
      FROM public.store_paid_ad_campaigns c
    UNION ALL
    SELECT 'banner'::text, c.id, c.store_id, c.owner_user_id,
           coalesce(c.lifecycle_status, 'DRAFT'), c.review_status, c.review_notes,
           c.title, c.subtitle, c.image_url, coalesce(c.campaign_source, 'OWNER_PAID'),
           c.start_at, c.end_at, c.submitted_at, c.created_at, c.updated_at,
           ARRAY(SELECT i.key FROM public.delivery_banner_campaign_inventories ci
                   JOIN public.delivery_ad_inventories i ON i.id = ci.inventory_id
                  WHERE ci.campaign_id = c.id ORDER BY ci.priority, ci.created_at, i.key),
           c.sort_order
      FROM public.store_banner_ad_campaigns c
  )
  SELECT camp.product_kind, camp.id, camp.store_id, camp.owner_user_id, camp.lifecycle_status,
         camp.review_status, camp.review_notes, camp.title, camp.headline, camp.image_url,
         camp.campaign_source, camp.start_at, camp.end_at, camp.submitted_at, camp.created_at,
         camp.updated_at, camp.inventory_keys, s.store_name,
         nullif(lower(btrim(sc.slug)), '') AS store_primary_slug,
         nullif(lower(btrim(st.slug)), '') AS store_sub_slug,
         CASE
           -- 배너 소재 제작 필요 (비어 있음·제작 대기 placeholder)
           WHEN camp.product_kind = 'banner'
                AND (nullif(btrim(coalesce(camp.image_url, '')), '') IS NULL
                     OR btrim(camp.image_url) = p_pending_asset) THEN 'needs_creative'
           WHEN camp.lifecycle_status IN ('SUBMITTED', 'UNDER_REVIEW', 'CHANGES_REQUESTED') THEN 'review'
           WHEN camp.lifecycle_status IN ('APPROVED', 'SCHEDULED') THEN 'scheduled'
           WHEN camp.lifecycle_status = 'ACTIVE' THEN 'active'
           WHEN camp.lifecycle_status IN ('PAUSED_ADMIN', 'PAUSED_OWNER') THEN 'held'
           WHEN camp.lifecycle_status IN ('ENDED', 'TERMINATED', 'ARCHIVED', 'EXHAUSTED') THEN 'ended'
           WHEN camp.lifecycle_status = 'REJECTED' THEN 'rejected'
           ELSE NULL
         END AS list_bucket,
         camp.sort_order
    FROM camp
    LEFT JOIN public.stores s ON s.id = camp.store_id
    LEFT JOIN public.store_categories sc ON sc.id = s.store_category_id
    LEFT JOIN public.store_topics st ON st.id = s.store_topic_id;
$$;

-- from 20270601100100_r7_admin_delivery_ad_campaigns_page.sql
CREATE OR REPLACE FUNCTION public.admin_delivery_ad_action_queue_rows(p_pending_asset text)
RETURNS TABLE (
  case_id uuid,
  product_kind text,
  campaign_id uuid,
  owner_user_id uuid,
  updated_at timestamptz,
  funding_status text,
  bucket text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH cases AS (
    SELECT oc.id AS case_id, oc.product_kind,
           CASE WHEN oc.product_kind = 'store_sponsored' THEN oc.store_sponsored_campaign_id
                ELSE oc.banner_campaign_id END AS campaign_id,
           oc.owner_user_id, oc.updated_at
      FROM public.delivery_ad_operations_cases oc
     WHERE oc.status = 'WAITING_ADMIN'
       AND oc.product_kind IN ('store_sponsored', 'banner')
  ),
  joined AS (
    SELECT c.*,
           coalesce(sp.lifecycle_status, bn.lifecycle_status) AS lifecycle_status,
           coalesce(sp.review_notes, bn.review_notes) AS review_notes,
           coalesce(sp.campaign_source, bn.campaign_source) AS campaign_source,
           bn.image_url AS banner_image_url,
           CASE f.status WHEN 'SECURED' THEN 'FUNDED' WHEN 'REFUNDED' THEN 'REFUNDED' ELSE 'UNFUNDED' END AS funding_status
      FROM cases c
      LEFT JOIN public.store_paid_ad_campaigns sp
        ON c.product_kind = 'store_sponsored' AND sp.id = c.campaign_id
      LEFT JOIN public.store_banner_ad_campaigns bn
        ON c.product_kind = 'banner' AND bn.id = c.campaign_id
      LEFT JOIN public.delivery_ad_canonical_bc_fundings f
        ON f.product_kind = c.product_kind AND f.application_id = c.campaign_id
     WHERE c.campaign_id IS NOT NULL
  )
  SELECT j.case_id, j.product_kind, j.campaign_id, j.owner_user_id, j.updated_at, j.funding_status,
         CASE
           WHEN j.product_kind = 'banner'
                AND (nullif(btrim(coalesce(j.banner_image_url, '')), '') IS NULL
                     OR btrim(j.banner_image_url) = p_pending_asset) THEN 'needs_creative'
           WHEN btrim(coalesce(j.lifecycle_status, '')) = 'SUBMITTED'
                AND btrim(coalesce(j.review_notes, '')) <> '' THEN 'resubmit'
           WHEN btrim(coalesce(j.lifecycle_status, '')) = 'SUBMITTED' THEN 'new_application'
           ELSE 'awaiting_review'
         END AS bucket
    FROM joined j
   -- 결제 확인: 디바이 직접 등록은 항상 · 광고주 유료는 FUNDED 만 (`isDeliveryAdFundingReadyForGoLive`)
   WHERE btrim(coalesce(j.campaign_source, 'OWNER_PAID')) = 'DIBAY_FIRST_PARTY'
      OR j.funding_status = 'FUNDED';
$$;

-- from 20270601100100_r7_admin_delivery_ad_campaigns_page.sql
CREATE OR REPLACE FUNCTION public.admin_delivery_ad_campaigns_page(
  p_product text,
  p_view text,
  p_store_id uuid,
  p_owner_user_id uuid,
  p_inventory_key text,
  p_primary_slug text,
  p_sub_slug text,
  p_pending_asset text,
  p_limit integer,
  p_offset integer
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH params AS (
    SELECT CASE WHEN p_product IN ('store_sponsored', 'banner') THEN p_product END AS product,
           coalesce(nullif(btrim(coalesce(p_view, '')), ''), 'all') AS view,
           nullif(btrim(coalesce(p_inventory_key, '')), '') AS inv,
           nullif(lower(btrim(coalesce(p_primary_slug, ''))), '') AS primary_slug,
           nullif(lower(btrim(coalesce(p_sub_slug, ''))), '') AS sub_slug,
           LEAST(100, GREATEST(1, coalesce(p_limit, 20))) AS lim,
           LEAST(100000, GREATEST(0, coalesce(p_offset, 0))) AS off
  ),
  idx AS (
    SELECT * FROM public.admin_delivery_ad_campaign_index(p_pending_asset)
  ),
  -- 상품·매장·광고주 + 노출 위치(BROWSE 분류) 필터 = 요약·정책 건수의 기준
  scoped AS (
    SELECT x.*
      FROM idx x, params pr
     WHERE (pr.product IS NULL OR x.product_kind = pr.product)
       AND (p_store_id IS NULL OR x.store_id = p_store_id)
       AND (p_owner_user_id IS NULL OR x.owner_user_id = p_owner_user_id)
       AND (pr.inv IS NULL OR (
             pr.inv = ANY (x.inventory_keys)
             AND (pr.inv <> 'STORES_CATEGORY_FEED' OR pr.primary_slug IS NULL OR (
                   coalesce(x.store_primary_slug, '') = pr.primary_slug
                   AND (pr.sub_slug IS NULL OR coalesce(x.store_sub_slug, '') = pr.sub_slug)))))
  ),
  filtered AS (
    SELECT sc.*
      FROM scoped sc, params pr
     WHERE pr.view = 'all'
        OR (pr.view = 'actionable' AND sc.list_bucket IN ('needs_creative', 'review'))
        OR (pr.view = 'history' AND sc.list_bucket IN ('ended', 'rejected'))
        OR sc.list_bucket = pr.view
  ),
  -- 오늘 요약 (전체 기준 — 필터 무관): 처리 Case 묶음 + 캠페인 목록 버킷
  queue AS (
    SELECT q.campaign_id, q.product_kind, q.bucket
      FROM public.admin_delivery_ad_action_queue_rows(p_pending_asset) q
  ),
  today AS (
    SELECT
      (SELECT count(*) FROM queue WHERE bucket = 'new_application') AS new_n,
      (SELECT count(*) FROM queue WHERE bucket = 'resubmit') AS resubmit_n,
      (SELECT count(*) FROM queue WHERE bucket = 'needs_creative') AS needs_n,
      (SELECT count(*) FROM queue WHERE bucket = 'awaiting_review')
        + (SELECT count(*) FROM idx x
            WHERE x.list_bucket = 'review'
              AND NOT EXISTS (SELECT 1 FROM queue q WHERE q.campaign_id = x.id)) AS pending_review_n,
      (SELECT count(*) FROM idx WHERE list_bucket = 'scheduled') AS scheduled_n,
      (SELECT count(*) FROM idx WHERE list_bucket = 'active') AS active_n,
      (SELECT count(*) FROM idx WHERE list_bucket = 'held') AS held_n,
      (SELECT count(*) FROM idx WHERE lifecycle_status IN ('PAUSED_OWNER', 'PAUSED_ADMIN')) AS paused_n
  ),
  paged AS (
    SELECT f.product_kind, f.id, f.updated_at
      FROM filtered f
     ORDER BY f.updated_at DESC, (f.product_kind = 'banner') ASC, f.id DESC
     LIMIT (SELECT lim FROM params)
    OFFSET (SELECT off FROM params)
  )
  SELECT jsonb_build_object(
    'total', (SELECT count(*) FROM filtered),
    'summary', (SELECT jsonb_build_object(
        'total', count(*),
        'review', count(*) FILTER (WHERE list_bucket = 'review'),
        'active', count(*) FILTER (WHERE list_bucket = 'active'),
        'held', count(*) FILTER (WHERE list_bucket = 'held'),
        'ended', count(*) FILTER (WHERE list_bucket IN ('ended', 'rejected'))) FROM scoped),
    'policy_counts', CASE WHEN (SELECT inv FROM params) IS NULL THEN NULL ELSE (
      SELECT jsonb_build_object(
        'linked', count(*),
        'exposable_now', count(*) FILTER (WHERE lifecycle_status = 'ACTIVE'),
        'under_review', count(*) FILTER (WHERE lifecycle_status IN ('SUBMITTED', 'UNDER_REVIEW', 'CHANGES_REQUESTED')))
        FROM scoped) END,
    'today_counts', (SELECT jsonb_build_object(
        'new', new_n, 'resubmit', resubmit_n, 'needs_production', needs_n,
        'pending_review', pending_review_n, 'scheduled', scheduled_n, 'active', active_n,
        'pending_payment', held_n, 'paused', paused_n) FROM today),
    'rows', coalesce((
      SELECT jsonb_agg(jsonb_build_object('product_kind', pg.product_kind, 'id', pg.id)
                       ORDER BY pg.updated_at DESC, (pg.product_kind = 'banner') ASC, pg.id DESC)
        FROM paged pg
    ), '[]'::jsonb)
  );
$$;
